<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth\Stub;

use Civi\Lughauth\Features\OAuth\Par\Domain\Gateway\ParRequestGateway;
use Civi\Lughauth\Features\OAuth\Par\Domain\ParRequest;

class InMemoryParRequestStore implements ParRequestGateway
{
    /** @var array<string, ParRequest> */
    private array $requests = [];

    public function store(ParRequest $request): void
    {
        $this->requests[$request->requestUri] = $request;
    }

    public function findByUri(string $requestUri, string $tenant): ?ParRequest
    {
        $entry = $this->requests[$requestUri] ?? null;
        if ($entry === null || $entry->tenant !== $tenant) {
            return null;
        }
        return $entry;
    }

    public function consume(string $requestUri, string $tenant): bool
    {
        $entry = $this->findByUri($requestUri, $tenant);
        if ($entry === null || $entry->isUsed() || $entry->isExpired()) {
            return false;
        }
        $this->requests[$requestUri] = new ParRequest(
            requestUri: $entry->requestUri,
            tenant: $entry->tenant,
            clientId: $entry->clientId,
            params: $entry->params,
            expiresAt: $entry->expiresAt,
            usedAt: new \DateTimeImmutable(),
        );
        return true;
    }

    public function purgeExpired(): void
    {
        $this->requests = array_filter($this->requests, static fn (ParRequest $request): bool => !$request->isExpired());
    }
}
